contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(amount > 0);
        require(amount <= c.totalRemaining());
        require(!c.blacklist(address(this)));
        uint valueBefore = c.value(); if (__ESBMC_reverted()) return;
        if (valueBefore > c.totalRemaining()) {
            valueBefore = c.totalRemaining();
        }
        // fund: only the owner can burn; instead simply check receipt of valueBefore
        c.getTokens(); if (__ESBMC_reverted()) return;
        uint bal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blacklisted = c.blacklist(address(this)); if (__ESBMC_reverted()) return;
        assert(bal == valueBefore && blacklisted && c.totalDistributed() == 200000000e18 + valueBefore);
    }
    receive() external payable {}
}

